/**
 * IWACU RWANDA — Nationwide boundary ingest.
 *
 * Reads the validated GeoJSON generated by scripts/download-rwanda-boundaries.ts
 * and upserts it to PostGIS in batches. The SQL RPC also dissolves villages
 * into their parent cell, sector and district polygons.
 *
 * Required environment:
 *   NEXT_PUBLIC_SUPABASE_URL
 *   SUPABASE_SERVICE_ROLE_KEY  (server-only; never commit)
 *
 * Usage:
 *   npx tsx scripts/ingest-boundaries.ts public/offline/rwanda-village-boundaries.geojson
 */
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { createClient } from "@supabase/supabase-js";

const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL;
const SERVICE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;
const BATCH_SIZE = 40;

if (!SUPABASE_URL || !SERVICE_KEY) {
  console.error("Missing NEXT_PUBLIC_SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY.");
  process.exit(1);
}

const supabase = createClient(SUPABASE_URL, SERVICE_KEY, {
  auth: { autoRefreshToken: false, persistSession: false },
});

type BoundaryGeometry = {
  type: "Polygon" | "MultiPolygon";
  coordinates: unknown;
};

type SourceFeature = {
  type: "Feature";
  properties?: Record<string, unknown>;
  geometry?: BoundaryGeometry;
};

type SourceCollection = {
  type: "FeatureCollection";
  features: SourceFeature[];
};

type BatchFeature = {
  scope_code: string;
  path: string;
  name_kiny: string;
  name_eng: string | null;
  level: string;
  geom: BoundaryGeometry;
  province_scope_code: string | null;
  province_name: string | null;
  province_name_eng: string | null;
  district_scope_code: string | null;
  district_name: string | null;
  sector_scope_code: string | null;
  sector_name: string | null;
  cell_scope_code: string | null;
  cell_name: string | null;
};

function textValue(props: Record<string, unknown>, key: string): string {
  const actualKey = Object.keys(props).find(
    (candidate) => candidate.toLowerCase() === key.toLowerCase()
  );
  const value = actualKey ? props[actualKey] : undefined;
  return value === undefined || value === null ? "" : String(value).trim();
}

function normaliseLevel(raw: unknown): string {
  const value = String(raw ?? "village").toLowerCase();
  const mapping: Record<string, string> = {
    adm5: "village",
    village: "village",
    umudugudu: "village",
    adm4: "cell",
    cell: "cell",
    akagari: "cell",
    adm3: "sector",
    sector: "sector",
    umurenge: "sector",
    adm2: "district",
    district: "district",
    akarere: "district",
    adm1: "province",
    province: "province",
    intara: "province",
  };
  return mapping[value] ?? "village";
}

function mainFeature(feature: SourceFeature, index: number): BatchFeature {
  const props = feature.properties ?? {};
  const scopeCode = textValue(props, "scope_code");
  const nameKiny = textValue(props, "name_kiny") || textValue(props, "village");
  const nameEng = textValue(props, "name_eng") || textValue(props, "village") || null;

  if (!/^RW(?:-[A-Z0-9]+)+$/.test(scopeCode)) {
    throw new Error(`Feature ${index} has a missing or invalid scope_code.`);
  }
  if (!nameKiny) throw new Error(`Feature ${index} (${scopeCode}) has no place name.`);
  if (!feature.geometry || !["Polygon", "MultiPolygon"].includes(feature.geometry.type)) {
    throw new Error(`Feature ${index} (${scopeCode}) has no supported polygon geometry.`);
  }

  return {
    scope_code: scopeCode,
    path: textValue(props, "path") || scopeCode.replace(/-/g, "."),
    name_kiny: nameKiny,
    name_eng: nameEng,
    level: normaliseLevel(props.level),
    geom: feature.geometry,
    province_scope_code: textValue(props, "province_scope_code") || null,
    province_name: textValue(props, "province_name") || null,
    province_name_eng: textValue(props, "province_name_eng") || null,
    district_scope_code: textValue(props, "district_scope_code") || null,
    district_name: textValue(props, "district_name") || null,
    sector_scope_code: textValue(props, "sector_scope_code") || null,
    sector_name: textValue(props, "sector_name") || null,
    cell_scope_code: textValue(props, "cell_scope_code") || null,
    cell_name: textValue(props, "cell_name") || null,
  };
}

async function main() {
  const input = process.argv[2] ?? "public/offline/rwanda-village-boundaries.geojson";
  const path = resolve(input);
  console.log(`Reading ${path}…`);

  let collection: SourceCollection;
  try {
    collection = JSON.parse(readFileSync(path, "utf8")) as SourceCollection;
  } catch (error) {
    throw new Error(`Could not read GeoJSON at ${path}: ${String(error)}`);
  }
  if (collection.type !== "FeatureCollection" || !Array.isArray(collection.features)) {
    throw new Error("Invalid GeoJSON: expected a FeatureCollection.");
  }
  if (collection.features.length < 14_000) {
    throw new Error(
      `Refusing to ingest only ${collection.features.length} features. Download and validate the national dataset first.`
    );
  }

  const prepared = collection.features.map(mainFeature);
  const villageCodes = new Set(prepared.map((feature) => feature.scope_code));
  if (villageCodes.size !== prepared.length) {
    throw new Error("Duplicate scope_code values found; no ingest was started.");
  }
  console.log(`Validated ${prepared.length} unique features. Sending batches of ${BATCH_SIZE}…`);

  let villageRowsUpserted = 0;
  for (let start = 0; start < prepared.length; start += BATCH_SIZE) {
    const batch = prepared.slice(start, start + BATCH_SIZE);
    const { data, error } = await supabase.rpc("ingest_boundary_batch", {
      p_features: batch,
    });
    if (error) {
      throw new Error(
        `Boundary ingest failed at batch ${Math.floor(start / BATCH_SIZE) + 1}: ${error.message}. Ensure the updated sql/schema.sql has been applied.`
      );
    }
    villageRowsUpserted += batch.length;
    if (villageRowsUpserted % 400 === 0 || start + batch.length === prepared.length) {
      console.log(
        `  Processed ${Math.min(start + batch.length, prepared.length)} / ${prepared.length} village features (RPC reported ${String(data ?? "success")}).`
      );
    }
  }

  console.log("\n── Summary ──");
  console.log(`  Village features upserted: ${villageRowsUpserted}`);
  console.log("  District/sector/cell polygons are aggregated by PostGIS from official village polygons.");
  console.log("  Leader contact data is separate and must be verified/imported from a trusted source.");
  console.log("  Source: NISR Village Boundary 2022. Review the source coverage notice.");
}

main().catch((error) => {
  console.error("Boundary ingest failed:", error);
  process.exitCode = 1;
});
